def schedule_epilogue(root: Path, source: str) -> dict[str, Any]:
    """Event-trigger the existing zero-model epilogue after a terminal edge."""
    log_path = root / "data" / "orchestration" / "terminal_epilogue.log"
    log_path.parent.mkdir(parents=True, exist_ok=True)
    marker = root / "data" / "orchestration" / "terminal_epilogue.pid"
    claim = root / "data" / "orchestration" / ".terminal_epilogue.lock"
    with locked(claim):
        prior_pid = None
        try:
            prior_pid = int(marker.read_text(encoding="ascii").strip())
        except (OSError, ValueError):
            pass
        if prior_pid:
            try:
                if os.name == "nt":
                    handle = ctypes.windll.kernel32.OpenProcess(0x1000, False, prior_pid)
                    alive = bool(handle)
                    if handle:
                        ctypes.windll.kernel32.CloseHandle(handle)
                else:
                    os.kill(prior_pid, 0)
                    alive = True
            except (OSError, TypeError):
                alive = False
            if alive:
                return {"status": "coalesced", "pid": prior_pid, "source": source}
        log = log_path.open("ab")
        kwargs: dict[str, Any] = {
            "cwd": str(root), "env": {**os.environ, "LOOP_ROOT": str(root)},
            "stdin": subprocess.DEVNULL, "stdout": log, "stderr": subprocess.STDOUT,
            "close_fds": True,
        }
        if os.name == "nt":
            kwargs["creationflags"] = (getattr(subprocess, "CREATE_NO_WINDOW", 0)
                                       | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0))
        else:
            kwargs["start_new_session"] = True
        try:
            proc = subprocess.Popen(
                [sys.executable, str(root / "harness" / "orchestration_epilogue.py")],
                **kwargs)
            marker.write_text(str(proc.pid), encoding="ascii")
            return {"status": "scheduled", "pid": proc.pid, "source": source}
        finally:
            log.close()


